-- See https://wiki.hypr.land/configuring/core/environment-variables/

-- Cursor theme (previously auto-generated by DMS in dms/cursor.lua).
-- Both the Hyprland-native (HYPRCURSOR) and the Xcursor name are set so
-- XWayland apps match; Bibata ships Xcursor-only, which hyprcursor loads natively.
hl.env("HYPRCURSOR_THEME", "Bibata-Modern-Ice")
hl.env("XCURSOR_THEME", "Bibata-Modern-Ice")
hl.env("HYPRCURSOR_SIZE", "30")
hl.env("XCURSOR_SIZE", "30")

-- Input method env vars for fcitx5. Wayland-native apps don't need them (they use
-- the text-input protocol), but XWayland apps only find the IME through these.
hl.env("GTK_IM_MODULE", "fcitx")
hl.env("QT_IM_MODULE", "fcitx")
hl.env("XMODIFIERS", "@im=fcitx")


