hl.config({
    general = {
        gaps_in          = 4,
        gaps_out         = 12,

        border_size      = 2,

        col              = {
            -- colors[1] (blue) sits at the bottom-left corner, colors[2] (pink) at the
            -- top-right: with y=0 at the top, angle 315 maps progress 0 to (0,1) and
            -- 1 to (1,0) (gradient.glsl: 1-y for the y axis, x for the x axis).
            active_border   = { colors = { "rgba(3399ffee)", "rgba(e4007fee)" }, angle = 315 },
            inactive_border = "rgba(595959aa)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/configuring/extra/tearing/ before you turn this on
        allow_tearing    = true,

        layout           = "dwindle",
