-- See https://wiki.hypr.land/configuring/layouts/dwindle-layout/ for more
hl.config({
    dwindle = {
        preserve_split = true, -- You probably want this
    },
})

-- See https://wiki.hypr.land/configuring/layouts/master-layout/ for more
hl.config({
    master = {
        new_status = "master",
    },
})

-- See https://wiki.hypr.land/configuring/layouts/scrolling-layout/ for more
hl.config({
    scrolling = {
        fullscreen_on_one_column = true,  -- single-column workspaces keep normal (non-fullsize) column width
        wrap_focus               = false, -- arrow-key focus stops at the edges instead of wrapping
        wrap_swapcol             = false, -- column swaps stop at the edges instead of wrapping
        follow_focus             = 0,     -- focusing a window no longer scrolls the tape to it
    },
})

-- Per-monitor layouts: only the main (centre) output scrolls, the side outputs dwindle.
-- Keyed by monitor selector so the rule follows workspaces wherever they are shown.
hl.workspace_rule({ workspace = "m[DP-3]", layout = "scrolling" })
hl.workspace_rule({ workspace = "m[DP-1]", layout = "dwindle" })
hl.workspace_rule({ workspace = "m[HDMI-A-1]", layout = "dwindle" })

-- Gaming workspace: id 100 (GAMING_WS_ID) on DP-3, named "gaming", scrolling.
-- Listed after the per-monitor rules on purpose: the later rule wins for `layout`.
hl.workspace_rule({
    workspace    = GAMING_WS,
    monitor      = "DP-3",
    layout       = "scrolling",
    default_name = GAMING_WS_NAME,
})

