---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "META" -- Meta/Super (lands on the physical left Alt key after the altwin swap)

-- Example binds, see https://wiki.hypr.land/configuring/core/binds/ for more
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(terminal))
-- Ghostty dropdown (quick) terminal: toggled via D-Bus IPC, works from any app.
hl.bind(mainMod .. " + grave", hl.dsp.exec_cmd("ghostty +toggle-quick-terminal"))
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M",
    hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + G", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", function() utils.toggleSplit() end) -- dwindle only
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser))

-- Audio output / mixer (ported from niri)
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("toggle-output"))
hl.bind(mainMod .. " + SHIFT + A",
    hl.dsp.exec_cmd("ghostty --title=wiremix --confirm-close-surface=false -e wiremix --tab output"))

-- Toggle the focused window's column between 100% of the monitor width and its
-- previous width (scrolling layout). Widths are remembered per window.
hl.bind(mainMod .. " + F", function() utils.toggleColumnWidth() end)

-- mainMod + SHIFT + F: toggle fullscreen, letting Hyprland pick the handler
-- (layout-aware on scrolling/layout workspaces, default elsewhere).
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ action = "toggle" }))

-- Move focus with mainMod + arrow keys. Left/right use the scrolling layout's own
-- "focus" message (which keeps the tape in view and, with wrap_focus = false, stops
-- at the edges) and Hyprland's native directional focus on every other layout.
hl.bind(mainMod .. " + left", function() utils.focusInWorkspace("l") end)
hl.bind(mainMod .. " + right", function() utils.focusInWorkspace("r") end)
hl.bind(mainMod .. " + up", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down", hl.dsp.focus({ direction = "down" }))

-- Cross monitors with mainMod + CTRL + left/right: focus the workspace the output
-- on that side is showing, which moves focus there too. Left/right above only walk
-- windows inside the current workspace and stop at its edges; this is the step past
-- the edge. The side is decided by the monitors' horizontal centres, so it follows
-- the layout (HDMI-A-1 | DP-3 | DP-1) rather than their names.
hl.bind(mainMod .. " + CTRL + left", function() utils.focusAdjacentMonitorWorkspace("l") end)
hl.bind(mainMod .. " + CTRL + right", function() utils.focusAdjacentMonitorWorkspace("r") end)

-- Move the focused window with mainMod + SHIFT + left/right. On the scrolling
-- layout `movewindow` pushes the window *into* the neighbouring column, turning
-- it into a vertical stack; its `swapcol` message swaps whole columns instead.
-- Dwindle has no columns, so there the native directional move is what we want.
hl.bind(mainMod .. " + SHIFT + left", function() utils.moveWindowInWorkspace("l") end)
hl.bind(mainMod .. " + SHIFT + right", function() utils.moveWindowInWorkspace("r") end)

-- mainMod + CTRL + SHIFT + left/right: send the focused window to the workspace
-- shown on the output on that side and follow it there. This is a normal
-- (non-silent) move, so Hyprland focuses the window and warps the cursor onto it.
hl.bind(mainMod .. " + CTRL + SHIFT + left", function() utils.moveWindowToAdjacentMonitorWorkspace("l") end)
hl.bind(mainMod .. " + CTRL + SHIFT + right", function() utils.moveWindowToAdjacentMonitorWorkspace("r") end)

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

-- Discord scratchpad: window rule parks it on special:chat, Alt+D shows/hides it
hl.bind(mainMod .. " + D", hl.dsp.workspace.toggle_special("chat"))

-- Scroll through workspaces with mainMod + scroll (mouse) or PgUp/PgDn, staying on
-- this output. Workspaces are walked numerically then by name, and stepping past the
-- last one creates the next (one spare ahead, not a ladder). With SHIFT the focused
-- window comes along to the same neighbour workspace.
hl.bind(mainMod .. " + mouse_down", function() utils.scrollWorkspace(1) end)
hl.bind(mainMod .. " + mouse_up", function() utils.scrollWorkspace(-1) end)

-- Same navigation on the keyboard: PgUp = previous workspace, PgDn = next workspace.
hl.bind(mainMod .. " + Page_Up", function() utils.scrollWorkspace(-1) end)
hl.bind(mainMod .. " + Page_Down", function() utils.scrollWorkspace(1) end)
hl.bind(mainMod .. " + SHIFT + Page_Up", function() utils.moveWindowWorkspace(-1) end)
hl.bind(mainMod .. " + SHIFT + Page_Down", function() utils.moveWindowWorkspace(1) end)

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"),
    { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),
    { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),
    { locked = true, repeating = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),
    { locked = true, repeating = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"), { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

---------------------------------------
---- GLOBAL SHORTCUTS (PORTAL) ----
---------------------------------------

-- Apps register these through the GlobalShortcuts portal (xdg-desktop-portal-hyprland);
-- Hyprland never grants/assigns triggers itself, so each one needs a bind here.
-- List the registered ids with: hyprctl globalshortcuts
hl.bind(mainMod .. " + V", hl.dsp.global("anomaly.hex:dictation-LOGO-v")) -- Hex dictation
hl.bind("CTRL_L + CTRL_R", hl.dsp.global("discord:discord-toggle-deafen"),
    -- non_consuming: a lone left/right Ctrl press is a *partial* chord match, which would
    -- otherwise be swallowed by the bind manager and never reach the focused app.
    { non_consuming = true }) -- Discord: toggle deafen


