-- See https://wiki.hypr.land/configuring/core/rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name           = "suppress-maximize-events",
    match          = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name     = "fix-xwayland-drags",
    match    = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Blur the vicinae launcher's layer surface (namespace "vicinae").
hl.layer_rule({
    name  = "vicinae-blur",
    match = { namespace = "^vicinae$" },
    blur  = true,
})

-- Keep Discord on its own special workspace (toggled with mainMod + D)
hl.window_rule({
    name      = "discord-special-chat",
    match     = { class = "^(discord)$" },
    workspace = "special:chat",
})

-- Steam, and whatever game it launches, go to the gaming workspace (id 100).
hl.window_rule({
    name      = "steam-gaming",
    match     = { class = "^(steam)$" },
    workspace = GAMING_WS,
})

hl.window_rule({
    name      = "steam-game-gaming",
    match     = { class = "^(gamescope|steam_app_.*)$" }, -- gamescope wrapper / native Steam games
    workspace = GAMING_WS,
})

-- wiremix audio mixer (mainMod + SHIFT + A) spawns floating
hl.window_rule({
    name  = "wiremix-floating",
    match = {
        -- ghostty is launched with --title=wiremix and wiremix keeps that title
        initial_title = "^wiremix$",
    },
    float = true,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})
